const payload = $input.first().json;
const body = payload.body && typeof payload.body === 'object' ? payload.body : payload;
const event = String(body.event || '');
const messageType = body.message_type;
const isIncoming = messageType === 'incoming' || messageType === 0;
const isPrivate = Boolean(body.private);
const status = String(body.conversation?.status || '');
const content = String(body.content || '').trim();
const senderType = String(body.sender?.type || '');
const handoffPattern = /asesor|persona|humano|agente|hablar con alguien|atenci[oó]n humana|reclamo|queja|gerente/i;
const wantsHuman = handoffPattern.test(content);
const shouldReply =
  event === 'message_created' &&
  isIncoming &&
  !isPrivate &&
  status === 'pending' &&
  Boolean(content) &&
  senderType !== 'agent_bot' &&
  senderType !== 'user';

return [{
  json: {
    shouldReply,
    wantsHuman,
    content,
    accountId: body.account?.id,
    conversationId: body.conversation?.id,
    contactName: body.sender?.name || 'Cliente',
    event,
    status,
    messageType,
    senderType,
  },
}];

const event = $input.first().json;
return [{
  json: {
    ...event,
    reply: 'Te conecto con un asesor humano. Seguiremos en esta misma conversación.',
    privateNote: `Handoff solicitado por ${event.contactName}. La IA dejó de responder. Para devolverla a la IA, cambia el estado a Pending.`,
    wantsHuman: true,
  },
}];

const event = $('Preparar evento').first().json;
const raw = String($input.first().json.output || $input.first().json.text || '').trim();
const wantsHuman = raw.includes('[[HANDOFF]]') || Boolean(event.wantsHuman);
const reply = raw.replace(/\[\[HANDOFF\]\]/g, '').trim() || 'Te conecto con un asesor humano. Seguiremos en esta misma conversación.';
return [{
  json: {
    ...event,
    reply,
    wantsHuman,
    privateNote: `Handoff solicitado por ${event.contactName}. La IA dejó de responder. Para devolverla a la IA, cambia el estado a Pending.`,
  },
}];
